"""Value extraction command."""
import sys,json,re,datetime
import tomlparse

def scalar(v):
    if isinstance(v,bool): return str(v).lower()
    if isinstance(v,str): return json.dumps(v,ensure_ascii=False)
    if isinstance(v,float): return repr(v)
    if isinstance(v,(datetime.date,datetime.time,datetime.datetime)):
        return v.isoformat().replace('+00:00','Z')
    return str(v)

def toml(v,level=0):
    if isinstance(v,list): return '[ '+', '.join(toml(x,level) for x in v)+' ]'
    if isinstance(v,dict): return '{ '+', '.join(f'{k} = {toml(x,level)}' for k,x in v.items())+' }'
    return scalar(v)

def pathparts(p):
    # Translate jq-style bracket forms to dotted components.
    p=re.sub(r'\[(\d+|\*)\]',r'.\1',p)
    return [x for x in p.strip('.').split('.') if x]

def select_one(obj,parts):
    if not parts: return [obj]
    key,*rest=parts; out=[]
    if isinstance(obj,dict):
        for k,v in obj.items():
            if key=='*' or ('*' in key and re.fullmatch(re.escape(key).replace(r'\*','.*'),k)) or key==k:
                out.extend(select_one(v,rest))
    elif isinstance(obj,list):
        if key=='*':
            for v in obj: out.extend(select_one(v,rest))
        elif key.isdigit() and int(key)<len(obj): out.extend(select_one(obj[int(key)],rest))
    return out

def run(args):
    fmt='value'; sep=None; strip=False; file=None; pattern=None; i=0
