import os
import re
import sys


def _split_comment(line):
    quote = None; escaped = False
    for i, c in enumerate(line):
        if escaped:
            escaped = False; continue
        if c == '\\' and quote == '"':
            escaped = True; continue
        if quote:
            if c == quote: quote = None
        elif c in ('"', "'"):
            quote = c
        elif c == '#':
            return line[:i], line[i:]
    return line, ''


def _eq_pos(line):
    quote = None; escaped = False; depth = 0
    for i, c in enumerate(line):
        if escaped:
            escaped = False; continue
        if c == '\\' and quote == '"':
            escaped = True; continue
        if quote:
            if c == quote: quote = None
        elif c in ('"', "'"):
            quote = c
        elif c in '[{(': depth += 1
        elif c in ']})': depth -= 1
        elif c == '=' and depth == 0:
            return i
    return -1


def _array(value, compact=True):
    # Normalize whitespace between simple array members while retaining quoted
    # strings and nested structures.
    if not value.startswith('[') or not value.rstrip().endswith(']'):
        return value.strip()
    inner = value.strip()[1:-1]
    if not inner.strip(): return '[]'
    parts=[]; start=0; quote=None; escaped=False; depth=0
    for i,c in enumerate(inner):
        if escaped: escaped=False; continue
        if c == '\\' and quote == '"': escaped=True; continue
        if quote:
            if c == quote: quote=None
        elif c in ('"', "'"): quote=c
        elif c in '[{(': depth+=1
        elif c in ']})': depth-=1
        elif c == ',' and depth == 0:
            parts.append(inner[start:i].strip()); start=i+1
    tail=inner[start:].strip()
    if tail: parts.append(tail)
    return '[' + ', '.join(parts) + ']' if compact else '[ ' + ', '.join(parts) + ' ]'


def _inline_table(value, compact=False):
    if not value.startswith('{') or not value.rstrip().endswith('}'):
        return value.strip()
    inner=value.strip()[1:-1]; fields=[]; start=0; quote=None; escaped=False; depth=0
    for i,c in enumerate(inner):
        if escaped: escaped=False; continue
        if c == '\\' and quote == '"': escaped=True; continue
        if quote:
            if c == quote: quote=None
        elif c in ('"', "'"): quote=c
        elif c in '[{(': depth+=1
        elif c in ']})': depth-=1
        elif c == ',' and depth == 0:
            fields.append(inner[start:i].strip()); start=i+1
