            def entry_key(text):
                body,_ = _split_comment(text)
                part=body.strip()
                p=_eq_pos(part) if part and not part.startswith(('#','[')) else -1
                return part[:p].strip() if p >= 0 else None
            if entry_key(lines[i]) is None:
                i+=1; continue
            j=i
