    for line_no,line in enumerate(lines):
        content, comment = _split_comment(line)
        stripped=content.strip()
        if not stripped:
            if comment:
                blank=0
                result.append(comment.strip())
                continue
            blank += 1
            if blank <= int(opts.get('allowed_blank_lines','2')): result.append('')
            continue
        blank=0
        out=stripped
        if not stripped.startswith('#') and not stripped.startswith('['):
            p=_eq_pos(stripped)
            if p >= 0:
                key=stripped[:p].strip(); val=stripped[p+1:].strip()
                val=_array(val, opts.get('compact_arrays','true') != 'false')
                val=_inline_table(val, opts.get('compact_inline_tables') == 'true')
                if opts.get('compact_entries') == 'true': out=f'{key}={val}'
                else:
                    pad=widths.get(line_no, len(key))
                    out=f'{key}{" " * (pad-len(key))} = {val}'
                if in_table and opts.get('indent_tables') == 'true':
                    out=opts.get('indent_string','  ')*table_depth+out
                elif in_table and opts.get('indent_entries') == 'true':
                    out=opts.get('indent_string','  ')+out
