    while result and result[-1] == '': result.pop()
    out=newline.join(result)
    if opts.get('trailing_newline','true') != 'false': out += newline
    return out


def run(args):
    if '--help' in args or '-h' in args:
        sys.stdout.write('''Format TOML documents.\n\nUsage: taplo format [OPTIONS] [FILES]...\n\nArguments:\n  [FILES]...  Paths or glob patterns to TOML documents.\n              If the only argument is "-", the standard input will be used.\n\nOptions:\n  -c, --config <CONFIG>       Path to the Taplo configuration file\n      --colors <COLORS>       [default: auto]\n      --no-auto-config        Do not search for a configuration file\n  -o, --option <OPTIONS>     A formatter option given as a "key=value"\n  -f, --force                 Ignore syntax errors and force formatting\n      --check                 Dry-run and report unformatted files\n      --diff                  Print the differences to stdout\n      --stdin-filepath <PATH> Treat stdin as content from a file\n  -h, --help                  Print help\n''')
        return 0
    check='--check' in args; diff='--diff' in args; force='--force' in args
    opts={}; files=[]; i=0
    while i<len(args):
        a=args[i]
        if a in ('--check','--diff','--force','--no-auto-config','--verbose','--log-spans'): i+=1; continue
        if a in ('--option','-o') and i+1<len(args):
            pair=args[i+1]; i+=2
            if '=' in pair:
                k,v=pair.split('=',1); opts[k]=v.lower()
            continue
        if a in ('--config','-c','--colors','--cache-path','--stdin-filepath') and i+1<len(args): i+=2; continue
        if a.startswith('-') and a!='-': i+=1; continue
        files.append(a); i+=1
    if not files or files == ['-']:
        src=sys.stdin.read()
        try:
            import tomlparse
            tomlparse.parse(src)
        except Exception:
            if not force: return 1
        out=format_text(src,opts)
        if check: return 1 if out != src else 0
        sys.stdout.write(out)
        return 0
    expanded=[]
    for pat in files:
        matches=glob.glob(pat,recursive=True)
        expanded.extend(matches if matches else ([pat] if os.path.isfile(pat) else []))
    status=0
    for path in expanded:
        try:
            src=open(path,encoding='utf-8').read()
            try:
                import tomlparse
                tomlparse.parse(src)
            except Exception:
                if not force: status=1; continue
            out=format_text(src,opts)
            if check:
                if out != src: status=1
            elif diff:
                sys.stdout.write(out)
            else:
                with open(path,'w',encoding='utf-8',newline='') as f: f.write(out)
        except OSError:
            status=1
    return status

