"""Independent command line entry point for the Taplo-compatible CLI."""
import sys
import misc_cli


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    # Clap accepts global switches before or after the command.
    if '--version' in args or '-V' in args:
        print('taplo 0.10.0')
        return 0
    if '--colors' in args:
        try:
            color = args[args.index('--colors') + 1]
        except IndexError:
            sys.stderr.write("error: a value is required for '--colors <COLORS>' but none was supplied\n  [possible values: auto, always, never]\n\nFor more information, try '--help'.\n")
            return 2
        if color not in ('auto', 'always', 'never'):
            sys.stderr.write(f"error: invalid value '{color}' for '--colors <COLORS>'\n  [possible values: auto, always, never]\n\nFor more information, try '--help'.\n")
            return 2
    if any(x.startswith('--colors=') for x in args):
        value = next(x.split('=', 1)[1] for x in args if x.startswith('--colors='))
        if value not in ('auto', 'always', 'never'):
            sys.stderr.write(f"error: invalid value '{value}' for '--colors <COLORS>'\n  [possible values: auto, always, never]\n\nFor more information, try '--help'.\n")
            return 2
    # Global switches are accepted on either side of the command.
    cleaned = []
    i = 0
    while i < len(args):
        if args[i] == '--colors':
            i += 2
        elif args[i] in ('--verbose', '--log-spans'):
            i += 1
        elif args[i].startswith('--colors='):
            i += 1
        else:
            cleaned.append(args[i]); i += 1
    args = cleaned
    if not args:
        # clap treats the command as required; a bare invocation prints
        # usage to stderr and exits with status 2.
        sys.stderr.write(misc_cli.TOP_SHORT_HELP)
        return 2
    if args[0].startswith('-') and args[0] not in ('-h', '--help', '-V', '--version'):
        sys.stderr.write(f"error: unexpected argument '{args[0]}' found\n\n")
        sys.stderr.write(misc_cli.TOP_SHORT_HELP)
        sys.stderr.write("\nFor more information, try '--help'.\n")
        return 2
    if misc_cli.run(args):
        return 0
    command, rest = args[0], args[1:]
    aliases = {'fmt': 'format', 'check': 'lint', 'validate': 'lint', 'cfg': 'config'}
    command = aliases.get(command, command)
    if command == 'config':
        import configcmd
        return configcmd.run(rest)
    if command == 'toml-test':
        import tomltest
        return tomltest.run()
    if command == 'lsp':
        import lspcmd
        return lspcmd.run(rest)
    # Command modules are contributed independently; resolve them when present.
    modules = {'format': ('formatcmd', 'run'), 'lint': ('lintcmd', 'run'),
               'get': ('getcmd', 'run'), 'completions': ('completioncmd', 'run')}
    if command in modules:
        modname, fn = modules[command]
        try:
            mod = __import__(modname)
        except ImportError:
            sys.stderr.write(f"error: {command} command unavailable\n")
            return 2
        result = getattr(mod, fn)(rest)
        return result if isinstance(result, int) else 0
    if command in ('-h', '--help', 'help'):
        if command == 'help' and rest:
            sub = aliases.get(rest[0], rest[0])
            modules_for_help = {'format': 'formatcmd', 'lint': 'lintcmd',
                                'get': 'getcmd', 'completions': 'completioncmd'}
            if sub in modules_for_help:
                try:
                    mod = __import__(modules_for_help[sub])
                    result = mod.run(['--help'])
                    return result if isinstance(result, int) else 0
                except ImportError:
                    pass
            if sub in ('config', 'cfg'):
                import configcmd
                return configcmd.run(['--help'])
            if sub == 'toml-test':
                sys.stdout.write('Start a decoder for `toml-test` (https://github.com/BurntSushi/toml-test)\n\nUsage: taplo toml-test [OPTIONS]\n')
                return 0
        sys.stdout.write(misc_cli.TOP_HELP)
        return 0
    if command in ('-V', '--version'):
        print('taplo 0.10.0')
        return 0
    sys.stderr.write(f"error: unrecognized subcommand '{command}'\n\nUsage: taplo [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n")
    return 2


if __name__ == '__main__':
    raise SystemExit(main())
