"""Small dependency-free TOML reader for the CLI's common document forms."""
import ast, datetime, json, re

class TomlError(ValueError): pass

class InlineTable(dict):
    """Distinguishes inline values from document table headers."""
    pass

class PreciseDateTime(datetime.datetime):
    """datetime carrying the source precision beyond Python's microseconds."""
    pass

class PreciseTime(datetime.time):
    """time retaining its normalized source precision."""
    pass

class TomlFloat(float):
    """Float retaining the spelling needed by toml-test for infinities."""
    def __new__(cls, value, source=None):
        obj=float.__new__(cls, value)
        obj.source=source
