"""Implementation of Taplo's toml-test decoder command."""
import sys, json, datetime
from decimal import Decimal

def _parse(text):
    try:
        import tomlparse
        return tomlparse.parse(text)
    except ImportError:
        try:
            import tomllib
            return tomllib.loads(text)
        except ImportError:
            raise RuntimeError('TOML parser unavailable')

def encode(v):
    if isinstance(v, dict): return {k: encode(x) for k,x in v.items()}
    if isinstance(v, list): return [encode(x) for x in v]
    if isinstance(v, bool): return {'type':'bool','value':str(v).lower()}
    if isinstance(v, int): return {'type':'integer','value':str(v)}
    if isinstance(v, float):
        if v == float('inf') and getattr(v, 'source', None) == '+inf':
            return {'type':'float','value':'+inf'}
        s=repr(v)
        if 'e' in s or 'E' in s:
            if v != 0 and 1e-5 <= abs(v) < 1e16:
                s=format(Decimal(s), 'f')
                if '.' not in s: s += '.0'
            else:
                a,b=s.lower().split('e')
                if a.endswith('.0'): a=a[:-2]
                s=a+'e'+str(int(b))
        return {'type':'float','value':s}
    if isinstance(v, datetime.datetime):
        kind='datetime' if v.tzinfo is not None else 'datetime-local'
        value=getattr(v,'_toml_raw',v.isoformat().replace('+00:00','Z'))
        return {'type':kind,'value':json.dumps(value)}
    if isinstance(v, datetime.date):
        return {'type':'date-local','value':json.dumps(v.isoformat())}
    if isinstance(v, datetime.time):
        return {'type':'time-local','value':json.dumps(getattr(v, '_toml_raw', None) or v.isoformat())}
    if isinstance(v, str): return {'type':'string','value':v}
    return v

def run(args=None):
    args = list(args or [])
    if args in (['-h'], ['--help']):
        import helpdata; helpdata.show('toml-test')
        return 0
    if args:
        arg = args[0]
        sys.stderr.write(f"error: unexpected argument '{arg}' found\n\nUsage: taplo toml-test [OPTIONS]\n\nFor more information, try '--help'.\n")
        return 2
    try:
        source=sys.stdin.read()
        obj=_parse(source)
        # The toml-test protocol emits one JSON value without a line ending.
        sys.stdout.write(json.dumps(encode(obj),ensure_ascii=False,separators=(',',':')))
        return 0
    except Exception as e:
        message=str(e)
        if 'duplicate key' in message:
            message='conflicting keys'
        elif 'trailing comma is not allowed' in message:
            pos=source.rfind(',')
            if pos >= 0: message += f' ({pos+1}..{pos+2})'
        sys.stderr.write(message+'\n')
        return 1
